        if (hidden(row)) return L('Restricted item')
        return row ? id + ' ' + (row.workEffortName || '') : id
    }
    const topOf = (id) => {
        let row = efforts[id]
        for (let guard = 0; row && row.parentWorkEffortId && efforts[row.parentWorkEffortId] && guard < 40; guard++) row = efforts[row.parentWorkEffortId]
        return row ? row.workEffortId : id
    }
    const names = {}
    const partyName = (id) => {
        if (!id) return L('None')
        if (!(id in names)) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
            names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
        }
        return names[id]
    }
    const clientOfProject = {}
    const projectClient = (projectId) => {
        if (!projectId) return null
        if (!(projectId in clientOfProject)) clientOfProject[projectId] = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projectId)
                .condition('roleTypeId', 'in', ['Customer', 'CustomerBillTo']).conditionDate('fromDate', 'thruDate', null).orderBy('fromDate').list())[0]?.partyId || null
        return clientOfProject[projectId]
    }
    const typeLabels = {}
    for (const type of ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkType').useCache(true).list()) typeLabels[type.enumId] = type.description || type.enumId
    const valueOf = (criterion, entry) => {
        const project = projectOf(entry)
        const isItem = entry.workEffortId && entry.workEffortTypeEnumId !== 'WetProject'
        switch (criterion) {
            case 'project': return {id: project, label: project ? (efforts[project]?.workEffortName || project) + ' (' + project + ')' : L('No project')}
            case 'topItem': return isItem ? {id: topOf(entry.workEffortId), label: itemLabel(topOf(entry.workEffortId))} : {id: null, label: L('The project itself')}
            case 'parent': return isItem && entry.parentWorkEffortId ? {id: entry.parentWorkEffortId, label: itemLabel(entry.parentWorkEffortId)}
                : {id: null, label: isItem ? L('Top level') : L('The project itself')}
            case 'workItem': return isItem ? {id: entry.workEffortId, label: itemLabel(entry.workEffortId)} : {id: null, label: L('The project itself')}
            case 'person': return {id: entry.partyId, label: partyName(entry.partyId)}
            case 'workType': return {id: entry.workTypeEnumId || null, label: entry.workTypeEnumId ? (typeLabels[entry.workTypeEnumId] || entry.workTypeEnumId) : L('No work type')}
