        for (let i = entries.length - 1; i >= 0; i--) if ((entries[i].clientPartyId || projectClient(projectOf(entries[i]))) !== clientPartyId) entries.splice(i, 1)
    }
    const rates = {}
    const rateOf = (entry) => {
        if (num(entry.clientHourRate) != null) return {amount: num(entry.clientHourRate), uom: null}
