        if (!(entry.rateAmountId in rates)) {
            const rate = ec.entity.find('mantle.humanres.rate.RateAmount').condition('rateAmountId', entry.rateAmountId).useCache(true).one()
            rates[entry.rateAmountId] = rate && rate.rateAmount != null ? {amount: num(rate.rateAmount), uom: rate.rateCurrencyUomId || null} : null
        }
        return rates[entry.rateAmountId]
    }
    const rows = {}
    const currencies = new Set()
    for (const entry of entries) {
        try {
            const day = ec.l10n.format(entry.fromDate, 'yyyy-MM-dd')
            const index = periodIndex[periodOf(day)]
            if (index == null) continue
            const hours = num(entry.hours) || 0
            const isBillable = entry.rateTypeEnumId !== 'RatpNoCharge'
            const values = criteriaList.map((criterion) => Object.assign({criterion: criterion}, valueOf(criterion, entry)))
            const key = values.map((value) => value.id == null ? '' : String(value.id)).join('|')
            const row = rows[key] || (rows[key] = {key: key, values: values, periodHours: periodList.map(() => 0), hours: 0, billableHours: 0, nonBillableHours: 0,
                amount: amountsShown ? 0 : undefined})
            row.periodHours[index] += hours
            row.hours += hours
            totals.periodHours[index] += hours
            totals.hours += hours
            totals.entryCount++
            if (isBillable) { row.billableHours += hours; totals.billableHours += hours } else { row.nonBillableHours += hours; totals.nonBillableHours += hours }
            if (amountsShown && isBillable) {
                const rate = rateOf(entry)
                if (rate == null) totals.missingRateCount++
                else {
                    const amount = round(hours * rate.amount)
                    row.amount += amount
                    totals.amount += amount
                    if (rate.uom) currencies.add(rate.uom)
                }
            }
        } catch (err) {
            ec.logger.error(`Time report: entry ${entry.timeEntryId} left out: ${err && err.message ? err.message : err}`)
        }
    }
    for (const row of Object.values(rows)) {
        row.periodHours = row.periodHours.map(round)
        row.hours = round(row.hours); row.billableHours = round(row.billableHours); row.nonBillableHours = round(row.nonBillableHours)
        if (amountsShown) row.amount = round(row.amount); else delete row.amount
        rowList.push(row)
    }
    rowList.sort((a, b) => {
        for (let i = 0; i < a.values.length; i++) {
            const diff = String(a.values[i].label).localeCompare(String(b.values[i].label))
            if (diff) return diff
        }
        return 0
    })
    totals.periodHours = totals.periodHours.map(round)
    totals.hours = round(totals.hours); totals.billableHours = round(totals.billableHours); totals.nonBillableHours = round(totals.nonBillableHours)
    if (amountsShown) {
        totals.amount = round(totals.amount)
        totals.mixedCurrency = currencies.size > 1
        totals.currencyUomId = currencies.size === 1 ? Array.from(currencies)[0] : (currencies.size ? null : 'USD')
    }
    // the chart: the first criterion's eight largest, the rest as Other
    try {
        const byFirst = {}
        for (const row of rowList) {
            const first = row.values[0]
            const key = first.id == null ? '' : String(first.id)
            const series = byFirst[key] || (byFirst[key] = {name: first.label, id: first.id, data: periodList.map(() => 0), hours: 0})
            row.periodHours.forEach((hours, i) => { series.data[i] += hours })
            series.hours += row.hours
        }
        const sorted = Object.values(byFirst).sort((a, b) => b.hours - a.hours)
        const shown = sorted.slice(0, 8)
        if (sorted.length > 8) {
            const other = {name: L('Other'), id: null, data: periodList.map(() => 0), hours: 0}
            for (const series of sorted.slice(8)) { series.data.forEach((hours, i) => { other.data[i] += hours }); other.hours += series.hours }
            shown.push(other)
        }
        chart.series = shown.map((series) => ({name: series.name, id: series.id, data: series.data.map(round), hours: round(series.hours)}))
    } catch (err) { ec.logger.error(`Time report: the chart left out: ${err && err.message ? err.message : err}`) }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const L = (text) => ec.l10n.localize(text)
