try {
    const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (!row || row.workEffortTypeEnumId !== 'WetProject' || !(scope.allProjects || Array.from(scope.visibleProjectIds || []).includes(workEffortId))) {
        ec.message.addError(ec.resource.expand('Project ${workEffortId} is not available', '', {workEffortId})); return }
    project = {workEffortId: row.workEffortId, workEffortName: row.workEffortName || row.workEffortId, statusId: row.statusId}
    const restricted = new Set(Array.from(scope.restrictedItemIds || []))
    const managed = new Set(Array.from(scope.managedProjectIds || []))
    const seen = (item) => scope.allProjects || !['WevRestricted', 'WevConfidential'].includes(item.visibilityEnumId) || managed.has(workEffortId) || restricted.has(item.workEffortId)
    const itemOf = (id) => {
        const item = id ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one() : null
        return item && item.rootWorkEffortId === workEffortId && item.workEffortTypeEnumId === 'WetTask' && seen(item) ? item : null
    }
    if (fromWorkEffortId) {
        const item = itemOf(fromWorkEffortId)
        if (!item) { ec.message.addError(ec.resource.expand('Work item ${fromWorkEffortId} is not available', '', {fromWorkEffortId})); return }
        fromItem = {workEffortId: item.workEffortId, workEffortName: item.workEffortName || item.workEffortId}
    }
    if (!parentWorkEffortId && !fromWorkEffortId) {
        try {
            ec.message.pushErrors()
            milestoneList = Array.from(ec.service.sync().name('mantle.work.ProjectServices.get#ProjectMilestoneSummary').parameters({workEffortId: workEffortId,
                timePerDay: timePerDay}).call()?.milestoneStatsList || []).map(strip)
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        } catch (err) {
            milestoneList = []
            ec.logger.error(`Progress of ${workEffortId}: the milestones left out: ${err && err.message ? err.message : err}`)
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    // the items' children counts and visibility, from one read of the project
    const childCount = {}
    const visibility = {}
    for (const item of ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).condition('workEffortTypeEnumId', 'WetTask')
            .condition('statusId', 'not-equals', 'WeCancelled').selectField('workEffortId').selectField('parentWorkEffortId').selectField('visibilityEnumId').list()) {
        visibility[item.workEffortId] = item.visibilityEnumId || null
        if (item.parentWorkEffortId) childCount[item.parentWorkEffortId] = (childCount[item.parentWorkEffortId] || 0) + 1
    }
    const maxDepth = Math.max(1, Math.min(6, Number(depth) || 1))
    const startId = parentWorkEffortId ? (itemOf(parentWorkEffortId)?.workEffortId || null) : (fromItem ? fromItem.workEffortId : workEffortId)
    if (!startId) { ec.message.addError(ec.resource.expand('Work item ${parentWorkEffortId} is not available', '', {parentWorkEffortId})); return }
    const levelOf = (id) => {
        ec.message.pushErrors()
        try {
            const list = Array.from(ec.service.sync().name('mantle.work.ProjectServices.get#WorkEffortChildStats').parameters({workEffortId: id, timePerDay: timePerDay})
                    .call()?.childStatsList || [])
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            return list
        } catch (err) {
            ec.logger.error(`Progress of ${workEffortId}: the items under ${id} left out: ${err && err.message ? err.message : err}`)
            return null
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    const walk = (id, level, parentId) => {
        const list = levelOf(id)
        if (!list) return []
        const out = []
        for (const stats of list) {
            if (!(stats.workEffortId in visibility)) continue
            if (!seen({workEffortId: stats.workEffortId, visibilityEnumId: visibility[stats.workEffortId]})) continue
            const one = Object.assign(strip(stats), {parentWorkEffortId: parentId, level: level, childCount: childCount[stats.workEffortId] || 0})
            rowList.push(one)
            out.push(one)
            if (level < maxDepth && one.childCount) walk(stats.workEffortId, level + 1, stats.workEffortId)
        }
        return out
    }
    const first = walk(startId, 1, parentWorkEffortId ? startId : (fromItem ? fromItem.workEffortId : null))
    // the totals of the first level
    const keys = ['estimatedWorkTime', 'remainingWorkTime', 'actualWorkTime', 'totalTimeAllowed'].concat(moneyShown ? money : [])
    const zero = toDecimal(0)
    const hundred = toDecimal(100)
    const sum = {workEffortId: null, workEffortName: L('Total')}
    for (const key of keys) sum[key] = first.reduce((total, one) => total.add(toDecimal(one[key] ?? 0)), zero)
    const perDay = toDecimal(timePerDay)
    const est = sum.estimatedWorkTime, budget = sum.totalTimeAllowed, act = sum.actualWorkTime, rem = sum.remainingWorkTime
    sum.estimatedWorkDays = est.divide(perDay); sum.remainingWorkDays = rem.divide(perDay); sum.actualWorkDays = act.divide(perDay); sum.totalTimeAllowedDays = budget.divide(perDay)
    sum.workActualPercent = est.isZero() ? zero : act.divide(est).multiply(hundred)
    sum.workActRemPercent = est.isZero() ? zero : act.add(rem).divide(est).multiply(hundred)
    sum.budgetActualPercent = budget.isZero() ? zero : act.divide(budget).multiply(hundred)
    sum.budgetActRemPercent = budget.isZero() ? zero : act.add(rem).divide(budget).multiply(hundred)
    totals = sum
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
